package org.millenaire.common.entity;import org.millenaire.common.utilities.Point;public class MillVillager{public net.minecraft.world.level.Level level;public Point dest;public boolean reject;public int swings,beans;public static class House{public float irrigation;public float getVillageIrrigation(){return irrigation;}}public House house=new House();public House getTownHall(){return house;}public Point getGoalDestPoint(){return dest;}public boolean setBlockstate(Point p,net.minecraft.world.level.block.state.BlockState s){if(reject)return false;Point.cells.put(p.pos,s);return true;}public void addToInv(net.minecraft.world.item.Item item,int meta,int count){if(item!=net.minecraft.world.item.Items.COCOA_BEANS||meta!=0)throw new AssertionError("Wrong cocoa item");beans+=count;}public void swing(net.minecraft.world.InteractionHand h){swings++;}}